def transform2(g):
    h=len(g); w=len(g[0])
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    lo=min(cnt,key=cnt.get)  # minority = barrier
    hi=max(cnt,key=cnt.get)  # majority = fill
    out=[row[:] for row in g]
    for r in range(h):
        bars=[c for c in range(w) if g[r][c]==lo]
        for i in range(len(bars)-1):
            for c in range(bars[i]+1,bars[i+1]):
                if out[r][c]==hi: out[r][c]=3
    for c in range(w):
        bars=[r for r in range(h) if g[r][c]==lo]
        for i in range(len(bars)-1):
            for r in range(bars[i]+1,bars[i+1]):
                if out[r][c]==hi: out[r][c]=3
    return out
